CREATE OR REPLACE FUNCTION public.create_ranked_run(p_mode text, p_rules_version text)
 RETURNS TABLE(run_id uuid, mode text, rules_version text, draft_seed text, run_token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_id uuid := auth.uid();
  clean_mode text := pg_catalog.btrim(p_mode);
  clean_rules_version text := pg_catalog.btrim(p_rules_version);
  generated_seed text;
  generated_token text;
  new_run public.game_runs%rowtype;
begin
  if caller_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if clean_mode is distinct from 'draft' then
    raise exception 'Invalid ranked mode' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.rulesets r
    where r.version = clean_rules_version and r.enabled
      and r.version in ('atu-classic-v2', 'atu-classic-v3', 'atu-history-draft-v1', 'atu-classic-v4', 'atu-history-draft-v2', 'atu-classic-v5', 'atu-history-draft-v3','atu-classic-v6','atu-history-draft-v4','atu-classic-v7','atu-history-draft-v5','atu-classic-v8','atu-history-draft-v6','atu-classic-v9','atu-history-draft-v7','atu-classic-v10','atu-history-draft-v8','atu-classic-v11','atu-history-draft-v9','atu-classic-v12','atu-history-draft-v10','atu-classic-v13','atu-history-draft-v11','atu-classic-v14','atu-history-draft-v12')
  ) then
    raise exception 'Rules version is not active' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(caller_id::text, 8134101)
  );

  -- Normal play must not consume or be blocked by pending duel slots.
  -- Keep four recent attempts; the newly requested run becomes the fifth.
  update public.game_runs as old
  set status = 'cancelled', updated_at = pg_catalog.now()
  where old.id in (
    select r.id from public.game_runs r
    where r.user_id = caller_id and r.mode in ('draft', 'pack')
      and r.status = 'started' and r.expires_at > pg_catalog.now()
    order by r.created_at desc, r.id desc offset 4
  );

  -- Unlimited daily attempts. Pending-run cleanup above is not a daily quota.

  generated_seed := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  generated_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');

  insert into public.game_runs (
    user_id, mode, rules_version, draft_seed, nonce_hash
  )
  values (
    caller_id,
    clean_mode,
    clean_rules_version,
    generated_seed,
    pg_catalog.encode(extensions.digest(generated_token, 'sha256'), 'hex')
  )
  returning * into new_run;

  return query
  select new_run.id, new_run.mode, new_run.rules_version, new_run.draft_seed,
    generated_token, new_run.expires_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_validated_run(p_run_id uuid, p_user_id uuid, p_run_token text, p_roster jsonb, p_transcript jsonb, p_score numeric, p_team_ovr numeric, p_projected_wins smallint, p_result_digest text)
 RETURNS TABLE(outcome text, challenge_status text, winner_profile_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  target_run public.game_runs%rowtype;
  target_challenge public.async_challenges%rowtype;
  player_side smallint;
  first_entry public.challenge_entries%rowtype;
  winner_user_id uuid;
  saved_entry public.leaderboard_entries%rowtype;
  saved_actions jsonb;
  incoming_prefix jsonb;
  action_count integer;
begin
  if p_run_token is null
    or pg_catalog.encode(extensions.digest(p_run_token, 'sha256'), 'hex') is null then
    raise exception 'Invalid run token' using errcode = '22023';
  end if;

  if p_roster is null
    or pg_catalog.jsonb_typeof(p_roster) <> 'object'
    or pg_catalog.octet_length(p_roster::text) > 65536 then
    raise exception 'Invalid roster payload' using errcode = '22023';
  end if;

  if p_transcript is null
    or pg_catalog.jsonb_typeof(p_transcript) <> 'array'
    or pg_catalog.octet_length(p_transcript::text) > 262144 then
    raise exception 'Invalid transcript payload' using errcode = '22023';
  end if;

  if p_score is null or p_score not between 0 and 1000000
    or p_team_ovr is null or p_team_ovr not between 0 and 200
    or p_projected_wins is null or p_projected_wins not between 0 and 82
    or p_result_digest is null or p_result_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid validated result' using errcode = '22023';
  end if;

  select r.*
  into target_run
  from public.game_runs r
  where r.id = p_run_id
  for update;

  if found and target_run.mode = 'pack' then
    raise exception 'Pack Mode is not eligible for rankings' using errcode = '22023';
  end if;
  if found and target_run.mode = 'draft'
    and (target_run.rules_version not in ('atu-classic-v2', 'atu-classic-v3', 'atu-history-draft-v1', 'atu-classic-v4', 'atu-history-draft-v2', 'atu-classic-v5', 'atu-history-draft-v3','atu-classic-v6','atu-history-draft-v4','atu-classic-v7','atu-history-draft-v5','atu-classic-v8','atu-history-draft-v6','atu-classic-v9','atu-history-draft-v7','atu-classic-v10','atu-history-draft-v8','atu-classic-v11','atu-history-draft-v9','atu-classic-v12','atu-history-draft-v10','atu-classic-v13','atu-history-draft-v11','atu-classic-v14','atu-history-draft-v12')
      or p_projected_wins <> 82 or p_score not between 1060 and 1120
      or p_score <> pg_catalog.round(p_score, 2)) then
    raise exception 'Only validated 82-0 Classic Drafts qualify' using errcode = '22023';
  end if;

  -- Keep one row per draft. Only append legal lineup swaps after its first save.
  -- The Edge Function replays every action before it calls this service-only RPC.
  if found and target_run.mode = 'draft' and target_run.status = 'completed' then
    if target_run.user_id <> p_user_id
      or target_run.nonce_hash <> pg_catalog.encode(extensions.digest(p_run_token, 'sha256'), 'hex') then
      raise exception 'Invalid run owner or token' using errcode = '22023';
    end if;
    select l.* into saved_entry from public.leaderboard_entries l where l.run_id = p_run_id;
    if not found then raise exception 'Invalid saved draft' using errcode = '22023'; end if;
    if saved_entry.result_digest = p_result_digest and saved_entry.transcript = p_transcript
      and saved_entry.roster = p_roster and saved_entry.points between 1060 and 1120 then
      return query select 'completed'::text, null::text, null::uuid;
      return;
    end if;
    if target_run.expires_at <= pg_catalog.now() then
      raise exception 'Run expired for ranking updates' using errcode = '22023';
    end if;
    action_count := pg_catalog.jsonb_array_length(saved_entry.transcript) - 1;
    saved_actions := saved_entry.transcript - action_count;
    select coalesce(pg_catalog.jsonb_agg(e.value order by e.ordinality), '[]'::jsonb)
      into incoming_prefix from pg_catalog.jsonb_array_elements(p_transcript) with ordinality e
      where e.ordinality <= action_count;
    if pg_catalog.jsonb_array_length(p_transcript) < action_count + 1
      or incoming_prefix <> saved_actions
      or p_transcript->-1->>'type' is distinct from 'arrange'
      or exists (
        select 1 from pg_catalog.jsonb_array_elements(p_transcript) with ordinality e
        where e.ordinality > action_count and e.ordinality < pg_catalog.jsonb_array_length(p_transcript)
          and e.value->>'type' is distinct from 'swap'
      ) then
      raise exception 'Invalid revision: only lineup swaps may follow the saved draft' using errcode = '22023';
    end if;
    if saved_entry.points between 1060 and 1120 and p_score < saved_entry.points then
      raise exception 'Invalid revision: best saved rating cannot decrease' using errcode = '22023';
    end if;
    if saved_entry.points not between 1060 and 1120 or p_score > saved_entry.points then
      update public.leaderboard_entries l set points = p_score, team_ovr = p_team_ovr,
        roster = p_roster, transcript = p_transcript, result_digest = p_result_digest,
        wins = 82, losses = 0
      where l.run_id = p_run_id;
      -- created_at remains the original save time; improvements do not move weeks.
    end if;
    return query select 'completed'::text, null::text, null::uuid;
    return;
  end if;

  -- A lost response can be retried, but only with the same owner, token and result.
  if found and target_run.status = 'completed' and target_run.mode in ('draft','pack')
    and target_run.user_id = p_user_id
    and target_run.nonce_hash = pg_catalog.encode(extensions.digest(p_run_token, 'sha256'), 'hex')
    and exists (select 1 from public.leaderboard_entries l
      where l.run_id = p_run_id and l.result_digest = p_result_digest
        and l.transcript = p_transcript and l.roster = p_roster) then
    return query select 'completed'::text, null::text, null::uuid;
    return;
  end if;

  if not found
    or target_run.user_id <> p_user_id
    or target_run.status <> 'started'
    or target_run.expires_at <= pg_catalog.now()
    or target_run.nonce_hash <>
      pg_catalog.encode(extensions.digest(p_run_token, 'sha256'), 'hex') then
    raise exception 'Run is invalid, expired or already consumed' using errcode = 'P0001';
  end if;

  if target_run.mode <> 'one_v_one' then
    insert into public.leaderboard_entries (
      run_id, user_id, mode, points, wins, losses, team_ovr,
      roster, transcript, result_digest, rules_version
    )
    values (
      target_run.id,
      target_run.user_id,
      target_run.mode,
      p_score,
      p_projected_wins,
      82 - p_projected_wins,
      p_team_ovr,
      p_roster,
      p_transcript,
      p_result_digest,
      target_run.rules_version
    );

    update public.game_runs r
    set status = 'completed', submitted_at = pg_catalog.now()
    where r.id = target_run.id;

    return query select 'completed'::text, null::text, null::uuid;
    return;
  end if;

  select c.*
  into target_challenge
  from public.async_challenges c
  where c.id = target_run.challenge_id
  for update;

  if not found or target_challenge.status in ('completed', 'expired', 'cancelled') then
    raise exception 'Challenge is not active' using errcode = 'P0001';
  end if;

  player_side := case
    when target_challenge.created_by = p_user_id then 1
    when target_challenge.opponent_id = p_user_id then 2
    else null
  end;

  if player_side is null
    or (player_side = 1 and target_challenge.status <> 'creator_drafting')
    or (player_side = 2 and target_challenge.status <> 'accepted') then
    raise exception 'Player cannot submit in the current challenge state' using errcode = 'P0001';
  end if;

  insert into public.challenge_entries (
    challenge_id, run_id, user_id, side, roster, transcript,
    score, team_ovr, projected_wins, result_digest
  )
  values (
    target_challenge.id, target_run.id, p_user_id, player_side,
    p_roster, p_transcript, p_score, p_team_ovr,
    p_projected_wins, p_result_digest
  );

  update public.game_runs r
  set status = 'completed', submitted_at = pg_catalog.now()
  where r.id = target_run.id;

  if player_side = 1 then
    update public.async_challenges c
    set status = 'open'
    where c.id = target_challenge.id;

    return query select 'creator_completed'::text, 'open'::text, null::uuid;
    return;
  end if;

  select e.*
  into first_entry
  from public.challenge_entries e
  where e.challenge_id = target_challenge.id and e.side = 1;

  if not found then
    raise exception 'Creator result is missing' using errcode = 'P0001';
  end if;

  winner_user_id := case
    when first_entry.score > p_score then first_entry.user_id
    when first_entry.score < p_score then p_user_id
    else null
  end;

  update public.async_challenges c
  set status = 'completed',
      winner_id = winner_user_id,
      completed_at = pg_catalog.now()
  where c.id = target_challenge.id;

  insert into public.leaderboard_entries (
    run_id, user_id, mode, points, wins, losses, team_ovr,
    roster, transcript, challenge_id, result_digest, rules_version
  )
  select
    e.run_id,
    e.user_id,
    'one_v_one',
    e.score,
    case
      when winner_user_id is null then 0
      when e.user_id = winner_user_id then 1
      else 0
    end,
    case
      when winner_user_id is null then 0
      when e.user_id = winner_user_id then 0
      else 1
    end,
    e.team_ovr,
    e.roster,
    e.transcript,
    target_challenge.id,
    e.result_digest,
    target_challenge.rules_version
  from public.challenge_entries e
  where e.challenge_id = target_challenge.id;

  return query
  select 'challenge_completed'::text, 'completed'::text, p.public_id
  from (select winner_user_id as id) w
  left join public.profiles p on p.id = w.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_card_cycle_rarity(p_run_id uuid, p_user_id uuid, p_pool text, p_release_fractions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r public.game_runs%rowtype;
  h jsonb;
  cycle_pool jsonb;
  tier_cards jsonb;
  tier_name text;
  card_entry jsonb;
  card_text text;
  all_shown jsonb := '[]'::jsonb;
  shown jsonb;
  snapshot jsonb;
  active jsonb;
  expected_pool text;
  release_value jsonb;
begin
  if p_pool is null or p_pool not in ('modern','history') then
    raise exception 'Invalid card-cycle pool';
  end if;
  if pg_catalog.jsonb_typeof(p_release_fractions) is distinct from 'object' then
    raise exception 'Invalid rarity release fractions';
  end if;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(p_release_fractions)) <> 5 then
    raise exception 'Invalid rarity release fractions';
  end if;
  foreach tier_name in array array['Bronze','Silver','Gold','Elite','Icon'] loop
    release_value := p_release_fractions->tier_name;
    if pg_catalog.jsonb_typeof(release_value) is distinct from 'number' then
      raise exception 'Invalid rarity release fraction';
    end if;
    if (release_value #>> '{}')::numeric <= 0 or (release_value #>> '{}')::numeric > 1 then
      raise exception 'Invalid rarity release fraction';
    end if;
  end loop;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text,8134101));
  select * into r from public.game_runs where id=p_run_id and user_id=p_user_id for update;
  if not found or r.mode <> 'draft' or r.status <> 'started' or r.expires_at <= pg_catalog.now()
    or r.rules_version not in ('atu-classic-v13','atu-history-draft-v11','atu-classic-v14','atu-history-draft-v12') then
    raise exception 'Active card-cycle draft not found';
  end if;
  expected_pool := case when r.rules_version in ('atu-classic-v13','atu-classic-v14') then 'modern' else 'history' end;
  if p_pool <> expected_pool then raise exception 'Card-cycle pool does not match rules'; end if;

  -- Retrying initialization returns the original replay snapshot and must never
  -- reactivate an older run after a newer run has become active.
  if r.draft_fairness is not null then
    if r.draft_fairness->>'kind' is distinct from 'card-cycle-rarity-v1' then
      raise exception 'Invalid card-cycle snapshot';
    end if;
    return r.draft_fairness;
  end if;

  insert into public.draft_offer_history(user_id) values(p_user_id) on conflict do nothing;
  select state into h from public.draft_offer_history where user_id=p_user_id for update;
  if pg_catalog.jsonb_typeof(coalesce(h->'card_cycles','{}'::jsonb)) is distinct from 'object'
    or pg_catalog.jsonb_typeof(coalesce(h->'card_cycle_active','{}'::jsonb)) is distinct from 'object' then
    raise exception 'Invalid stored card-cycle state';
  end if;
  cycle_pool := coalesce(h->'card_cycles'->p_pool,'{}'::jsonb);
  if pg_catalog.jsonb_typeof(cycle_pool) is distinct from 'object' then
    raise exception 'Invalid stored card-cycle pool';
  end if;
  foreach tier_name in array array['Bronze','Silver','Gold','Elite','Icon'] loop
    tier_cards := coalesce(cycle_pool->tier_name,'[]'::jsonb);
    if pg_catalog.jsonb_typeof(tier_cards) is distinct from 'array' then
      raise exception 'Invalid stored card-cycle tier';
    end if;
    for card_entry in select value from pg_catalog.jsonb_array_elements(tier_cards) loop
      card_text := card_entry #>> '{}';
      if pg_catalog.jsonb_typeof(card_entry) is distinct from 'number'
        or card_text is null or card_text !~ '^[0-9]+$' or card_text::numeric > 2147483647 then
        raise exception 'Invalid stored card-cycle card';
      end if;
    end loop;
    cycle_pool := pg_catalog.jsonb_set(cycle_pool,array[tier_name],tier_cards,true);
    all_shown := all_shown || tier_cards;
  end loop;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(all_shown))
    <> (select pg_catalog.count(distinct value) from pg_catalog.jsonb_array_elements(all_shown)) then
    raise exception 'Duplicate stored card-cycle card';
  end if;
  -- The tier arrays are chronological. Keep their order so positional scarcity
  -- can release the oldest eligible exact card, not the lowest numeric ID.
  shown := all_shown;
  snapshot := pg_catalog.jsonb_build_object('kind','card-cycle-rarity-v1','releaseFractions',p_release_fractions,'shown',shown);

  h := pg_catalog.jsonb_set(h,'{card_cycles}',coalesce(h->'card_cycles','{}'::jsonb),true);
  h := pg_catalog.jsonb_set(h,array['card_cycles',p_pool],cycle_pool,true);
  h := pg_catalog.jsonb_set(h,'{card_cycle_active}',coalesce(h->'card_cycle_active','{}'::jsonb),true);
  active := h->'card_cycle_active'->p_pool;
  if active is null or active->>'createdAt' is null or r.created_at >= (active->>'createdAt')::timestamptz then
    h := pg_catalog.jsonb_set(h,array['card_cycle_active',p_pool],
      pg_catalog.jsonb_build_object('runId',r.id,'createdAt',r.created_at),true);
  end if;
  update public.draft_offer_history set state=h,updated_at=pg_catalog.now() where user_id=p_user_id;
  update public.game_runs set draft_fairness=snapshot where id=p_run_id;
  return snapshot;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_card_cycle(p_run_id uuid, p_user_id uuid, p_events jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r public.game_runs%rowtype;
  h jsonb;
  pool_name text;
  cycle_pool jsonb;
  tier_cards jsonb;
  previous_events jsonb;
  previous_length integer;
  incoming_length integer;
  event_index integer;
  entry jsonb;
  event_type text;
  tier_name text;
  card_text text;
  card_id integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text,8134101));
  select * into r from public.game_runs where id=p_run_id and user_id=p_user_id for update;
  if not found or r.mode <> 'draft' or r.rules_version not in ('atu-classic-v12','atu-history-draft-v10','atu-classic-v13','atu-history-draft-v11','atu-classic-v14','atu-history-draft-v12') then
    raise exception 'Card-cycle draft not found';
  end if;
  if r.draft_fairness->>'kind' is distinct from (case when r.rules_version in ('atu-classic-v13','atu-history-draft-v11','atu-classic-v14','atu-history-draft-v12') then 'card-cycle-rarity-v1' else 'card-cycle-v1' end) then
    raise exception 'Card-cycle draft is not initialized';
  end if;
  if pg_catalog.jsonb_typeof(p_events) is distinct from 'array'
    or pg_catalog.octet_length(p_events::text)>65536 then
    raise exception 'Invalid card-cycle events';
  end if;
  incoming_length := pg_catalog.jsonb_array_length(p_events);
  if incoming_length>256 then raise exception 'Too many card-cycle events'; end if;
  previous_events := r.card_cycle_recorded;
  if pg_catalog.jsonb_typeof(previous_events) is distinct from 'array' then
    raise exception 'Invalid stored card-cycle journal';
  end if;
  previous_length := pg_catalog.jsonb_array_length(previous_events);

  -- Retried and out-of-order older cumulative checkpoints cannot double count.
  -- A longer checkpoint must extend the recorded prefix exactly.
  if incoming_length<=previous_length then return; end if;
  if previous_length>0 then
    for event_index in 0..previous_length-1 loop
      if p_events->event_index is distinct from previous_events->event_index then
        raise exception 'Card-cycle checkpoint diverged';
      end if;
    end loop;
  end if;

  pool_name := case when r.rules_version in ('atu-classic-v12','atu-classic-v13','atu-classic-v14') then 'modern' else 'history' end;
  select state into h from public.draft_offer_history where user_id=p_user_id for update;
  if not found then raise exception 'Card-cycle history not initialized'; end if;

  -- An earlier run stays independently replayable, but cannot clear protection
  -- established by the currently active run. Sequential restarts flush the old
  -- transcript before initializing the replacement run.
  if h->'card_cycle_active'->pool_name->>'runId' is distinct from r.id::text then return; end if;
  cycle_pool := h->'card_cycles'->pool_name;
  if pg_catalog.jsonb_typeof(cycle_pool) is distinct from 'object' then
    raise exception 'Invalid stored card-cycle pool';
  end if;

  for event_index in previous_length..incoming_length-1 loop
    entry := p_events->event_index;
    event_type := entry->>'type';
    tier_name := entry->>'tier';
    if pg_catalog.jsonb_typeof(entry) is distinct from 'object'
      or event_type is null or event_type not in ('offer','reset','release')
      or tier_name is null or tier_name not in ('Bronze','Silver','Gold','Elite','Icon') then
      raise exception 'Invalid card-cycle event';
    end if;
    tier_cards := coalesce(cycle_pool->tier_name,'[]'::jsonb);
    if pg_catalog.jsonb_typeof(tier_cards) is distinct from 'array' then
      raise exception 'Invalid stored card-cycle tier';
    end if;
    if event_type='reset' then
      tier_cards := '[]'::jsonb;
    else
      card_text := entry->>'cardId';
      if pg_catalog.jsonb_typeof(entry->'cardId') is distinct from 'number'
        or card_text is null or card_text !~ '^[0-9]+$' or card_text::numeric > 2147483647 then
        raise exception 'Invalid card-cycle card';
      end if;
      card_id := card_text::integer;
      if event_type='release' then
        select coalesce(pg_catalog.jsonb_agg(value order by ordinality),'[]'::jsonb)
          into tier_cards
          from pg_catalog.jsonb_array_elements(tier_cards) with ordinality
          where value<>pg_catalog.to_jsonb(card_id);
      elsif not tier_cards @> pg_catalog.jsonb_build_array(card_id) then
        tier_cards := tier_cards || pg_catalog.jsonb_build_array(card_id);
      end if;
    end if;
    cycle_pool := pg_catalog.jsonb_set(cycle_pool,array[tier_name],tier_cards,true);
  end loop;
  h := pg_catalog.jsonb_set(h,array['card_cycles',pool_name],cycle_pool,true);
  update public.draft_offer_history set state=h,updated_at=pg_catalog.now() where user_id=p_user_id;
  update public.game_runs set card_cycle_recorded=p_events where id=p_run_id;
end;
$function$
